create or replace view public.study_destination_metric_sg_v1 with (security_invoker=true) as select scope_id as country_code, metric_key, value, source_name, source_url, data_as_of, last_verified_at, confidence, evidence_kind, review_status from public.report_metric_evidence_country where scope_type='country' and scope_id='SG' and review_status='verified' and metric_key in ('country_population','student_living_cost_monthly_range','student_transport_reference','student_work_hours_limit','tuition_annual_low','tuition_annual_high','visa_application_fee','employment_focus_sectors'); revoke all on public.study_destination_metric_sg_v1 from anon, authenticated; grant select on public.study_destination_metric_sg_v1 to service_role;;
